package com.mzuriair.app;
import static org.junit.Assert.*; import com.google.gson.Gson; import com.mzuriair.app.data.model.Telemetry; import org.junit.Test;
public class TelemetryContractTest { @Test public void parsesFirmwareTelemetry(){String j="{\"device\":\"mzuriair-001\",\"ts\":1759400000,\"seq\":123,\"risk\":{\"level\":\"moderate\",\"aqi\":77,\"dominant\":\"PM2.5\",\"reasons\":1},\"metrics\":{\"PM2.5\":17.0,\"Temp\":23.4,\"Humidity\":48},\"vitals\":{\"hr\":84,\"wheeze\":false,\"wheeze_db\":4.2,\"activity\":\"rest\"},\"device_status\":{\"battery\":87,\"charging\":false,\"rssi\":-61},\"simulated\":true}";Telemetry t=new Gson().fromJson(j,Telemetry.class);assertEquals("MODERATE",t.riskLabel());assertEquals(77,t.risk.aqi);assertTrue(t.simulated);assertEquals("PM2.5",t.risk.dominant);assertEquals(84,t.vitals.hr,0.01);}}
